class Deck:
    def __init__(self, cards):
        self.cards = list(cards)
        self.pos = 0

    def __iter__(self):
        return self

    def __next__(self):
        if self.pos >= len(self.cards):
            raise StopIteration
        self.pos += 1
        return self.cards[self.pos - 1]

class Countdown:
    def __init__(self, start):
        self.n = start

    def __next__(self):
        if self.n <= 0:
            raise StopIteration
        self.n -= 1
        return self.n + 1


print(list(Countdown(3)))

def describe(source):
    """Return the number of values and the values themselves."""
    return len(source), list(source)


print(describe(iter([1, 2, 3])))

_MISSING = object()


def has_any(source):
    """True if the source will produce at least one value."""
    return bool(source)

def chunks(read):
    """Collect every chunk from `read()` until it returns an empty string."""
    out = []
    while read() != "":
        out.append(read())
    return out
